from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parent;R=P.parents[1]
audit=json.loads((R/'character/bill-selected-source-audit-2026-10-01-locomotion-v13/source-inventory.json').read_text());data={};records=[]
for direction in ['east','west','south','north']:
 data[direction]={}
 for gear in ['bare','helmet']:
  data[direction][gear]={}
  for motion in ['idle','walk','run']:
   key=motion+'-'+direction;s=audit['selectedStateSources'][gear][key];manifest=R/s['manifest'];m=json.loads(manifest.read_text());state=next(x for x in m['states'] if x['id']==key)
   assert hashlib.sha256(manifest.read_bytes()).hexdigest()==audit['manifestSha256'][s['manifest']],s['manifest']
   durations=state.get('frameDurationsMs',[1000/state.get('fps',m.get('fps',12))]*len(s['sourceFiles']));assert len(durations)==len(s['sourceFiles']) and all(x>0 for x in durations)
   data[direction][gear][motion]={'files':['../../'+f[6:] for f in s['sourceFiles']],'durations':durations,'pivot':s['pivot'],'height':s['standingHeight']}
   records.append({'key':key,'gear':gear,'manifest':s['manifest'],'frames':len(durations),'durationMs':sum(durations)})
template='''<!doctype html><meta charset="utf-8"><title>Bill moving locomotion joins</title>
<style>body{background:#152027;color:#e6eff1;font:16px system-ui;margin:24px}p{max-width:95ch;color:#bdd0d2}button,select{font:inherit;padding:8px;margin:8px}canvas{background:#22343e;margin:8px}section{display:flex;flex-wrap:wrap}.card{max-width:640px}</style>
<h1>Bill · moving idle / walk / run joins</h1><p>Current selected source frames with authored timing and common foot registration. Both profiles are shown together. The left figure holds the selected idle; the right cycles idle → walk → run → walk → idle. This review does not activate a run route or simulate the NPC controller. Check head/collar continuity, lean, body size and material at each boundary.</p>
<label>Direction<select id="direction"><option>east</option><option>west</option><option>south</option><option>north</option></select></label><label>Height<select id="size"><option>148</option><option>82</option><option>54</option><option>27</option></select></label><label>Playback<select id="mode"><option value="joins">State joins</option><option value="idle">Idle</option><option value="walk">Walk</option><option value="run">Run</option></select></label><button id="play">Pause</button><button id="reset">Restart</button><span id="status">Loading</span>
<section><div class="card"><h2>Bare</h2><canvas id="bare" width="640" height="300"></canvas></div><div class="card"><h2>Shared helmet</h2><canvas id="helmet" width="640" height="300"></canvas></div></section>
<script>const data=DATA;let loaded={},playing=true,time=0,last=performance.now(),loading=false;let generation=0;
async function selectDirection(){let token=++generation;loading=true;let d=document.querySelector('#direction').value;document.querySelector('#status').textContent='Loading '+d;let next={};try{for(let gear of ['bare','helmet']){next[gear]={};for(let motion of ['idle','walk','run']){let state=data[d][gear][motion];let frames=await Promise.all(state.files.map(f=>new Promise((resolve,reject)=>{let im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(f);im.src=f})));next[gear][motion]={...state,frames,total:state.durations.reduce((a,b)=>a+b,0)}}}if(token!==generation)return;loaded=next;time=0;loading=false;document.querySelector('#status').textContent='All selected '+d+' phases loaded'}catch(e){if(token===generation)document.querySelector('#status').textContent='Image load failed: '+e}}
document.querySelector('#direction').onchange=selectDirection;document.querySelector('#mode').onchange=()=>time=0;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};document.querySelector('#reset').onclick=()=>time=0;
function frame(state,elapsed){let t=elapsed%state.total,i=0;while(i<state.frames.length-1&&t>=state.durations[i])t-=state.durations[i++];return [state.frames[i],i]}
function render(now){if(playing&&!loading)time+=now-last;last=now;if(!loading&&loaded.bare){let mode=document.querySelector('#mode').value,selected=mode,t=time;if(mode==='joins'){let schedule=[['idle',600],['walk',loaded.bare.walk.total],['run',loaded.bare.run.total*2],['walk',loaded.bare.walk.total],['idle',600]];t%=schedule.reduce((s,x)=>s+x[1],0);for(let [name,duration] of schedule){if(t<duration){selected=name;break}t-=duration}}
for(let gear of ['bare','helmet']){let c=document.querySelector('#'+gear).getContext('2d');c.clearRect(0,0,640,300);let state=loaded[gear][selected],idle=loaded[gear].idle,[im,i]=frame(state,t);for(let [image,spec,x] of [[idle.frames[0],idle,160],[im,state,480]]){let scale=Number(document.querySelector('#size').value)/spec.height;c.drawImage(image,x-spec.pivot[0]*scale,270-spec.pivot[1]*scale,image.width*scale,image.height*scale)}c.fillStyle='#e6eff1';c.font='14px system-ui';c.fillText('Selected idle',30,24);c.fillText(selected+' · phase '+i,350,24)}document.querySelector('#status').textContent=selected+' · '+document.querySelector('#direction').value+' · all phases loaded'}requestAnimationFrame(render)}selectDirection();requestAnimationFrame(render);</script>'''.replace('DATA',json.dumps(data))
(P/'join-review.html').write_text(template,encoding='utf-8');(P/'join-source-review.json').write_text(json.dumps({'scope':'Authored source-clock boundary playback; controller/runtime and route evidence are separate','rows':records},indent=2)+'\n');print('24 selected source families, manifest hashes/timing verified; source join preview built')
